package com.gomgomapps.math.core;
import org.junit.Test;import static org.junit.Assert.*;import java.util.*;
public class NumberLineRelationsTest {
 @Test public void allPublicLineConditionsExhaustBeforeRepeating(){Generator generator=new Generator(new Random(120));List<String> recent=new ArrayList<>();Set<Integer> answers=new HashSet<>();Set<Integer> steps=new HashSet<>();var limits=GlobalCurriculum.limits("england-primary-2021-v1",NumberLineRelations.ID,1);for(int i=0;i<1012;i++){Question q=generator.next(NumberLineRelations.ID,recent,true,limits);assertFalse(recent.contains(q.signature()));recent.add(q.signature());double[] v=q.diagram.values;int expected=(int)(v[0]+v[1]*v[3]);answers.add(expected);steps.add((int)v[1]);assertTrue(v[0]>=0&&v[0]+10*v[1]<=100);q.answers=new String[]{"poison"};q.expression="wrong";Checker checker=new Checker();assertTrue(checker.check(q,List.of(),List.of(""+expected)).correct());assertEquals(0,checker.check(q,List.of(),List.of(""+(expected+1))).index);assertTrue(q.choices.isEmpty());assertFalse(HelpPlan.forQuestion(q).canTransfer());}assertEquals(101,answers.size());assertEquals(Set.of(1,10),steps);assertEquals(recent.get(0),generator.next(NumberLineRelations.ID,recent,false,limits).signature());Learning.Profile profile=new Learning.Profile();GlobalCurriculum.chooseCountry(profile,"GB");GlobalCurriculum.choosePack(profile,"england-primary-2021-v1");for(int grade:new int[]{1,2})assertTrue(GlobalCurriculum.pack(profile).inGrade(NumberLineRelations.ID,grade));}
 private void frames(int start,int step,int mark,int...expected){Question q=NumberLineRelations.make(start,step,mark);q.answers=new String[]{"wrong"};HelpPlan plan=HelpPlan.forQuestion(q);assertEquals(5,plan.size());for(int i=0;i<5;i++){assertTrue(plan.step(i).accepts(""+expected[i]));assertFalse(plan.step(i).accepts(""+(expected[i]+1)));assertFalse(plan.step(i).before.matches(".*\\d.*"));}assertFalse(plan.canTransfer());assertEquals(NumberLineRelations.VERSION,q.studyGuide.teachingVersion);}
 @Test public void endpointsAndMalformedDiagramDoNotRevealOrAcceptHiddenKeys(){frames(0,1,0,1,1,1,1,0);frames(0,10,10,0,10,10,100,100);frames(37,1,5,37,1,5,5,42);frames(0,10,6,0,10,6,60,60);Question q=NumberLineRelations.make(0,1,2);q.diagram.values[3]=2.5;assertNull(NumberLineRelations.read(q));assertEquals(Checker.Status.INPUT_NEEDED,new Checker().check(q,List.of(),List.of("2")).status);q=NumberLineRelations.make(0,1,2);q.diagram.values[0]=Double.NaN;assertNull(NumberLineRelations.read(q));}
 @Test public void verbalComparisonReusesExistingPicturesWithZeroAndPublicChecking(){for(String id:List.of("numberCompareWords","objectCompareWords")){Generator generator=new Generator(new Random(120));List<String> recent=new ArrayList<>();var limits=GlobalCurriculum.limits("england-primary-2021-v1",id,1);Set<Integer> outcomes=new HashSet<>();for(int i=0;i<100;i++){Question q=generator.next(id,recent,true,limits);assertFalse(recent.contains(q.signature()));recent.add(q.signature());int expected=Double.compare(q.diagram.values[0],q.diagram.values[1])+1;outcomes.add(expected);q.answers=new String[]{"poison"};assertTrue(new Checker().check(q,List.of(),List.of(""+expected)).correct());assertFalse(HelpPlan.forQuestion(q).canTransfer());}assertEquals(Set.of(0,1,2),outcomes);for(int[] values:new int[][]{{0,0},{0,20},{20,0},{20,20}}){Question q=PrimaryOrdering.make(id,values);q.answers=new String[]{"poison"};assertTrue(new Checker().check(q,List.of(),List.of(""+(Integer.compare(values[0],values[1])+1))).correct());}}}
}
